import java.util.*;

class Participant {
    String ticket, name;

    Participant(String t, String n) {
        ticket = t;
        name = n;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj)
            return true;

        if (!(obj instanceof Participant))
            return false;

        Participant p = (Participant) obj;
        return ticket.equals(p.ticket);
    }

    @Override
    public int hashCode() {
        return ticket.hashCode();
    }
}

public class Main {
    public static void main(String[] args) {
