import java.util.*;
interface Customer{
    double fc=100.0;
}
interface Bill{
    double calcBill(double units);
}

@FunctionalInterface
interface Discount{
    double calcdiscount(double amount);
}
class ElectricityBill implements Customer,Bill{
    @Override
    public double calcBill(double units);
    double rate;
    if(units>=0 && units <=100){
        rate=2.00;
    }
    if else(units>=101 && units <=200){
        rate=3.00;
    }
    else{
        rate=5.00;
    }
    double energy=units*rate;
    double gross=energy+fc;
    return gross;
}

class Main{
    public static void main(String[] args){
        Scanner in=new Scanner(System.in);
        String name=in.next();
        double units=nextDouble();
        ElectricityBill b=new ElectricityBill();
        double energy=b.calcBill(units);
        double grossbill==energy+Customer.fc;
        Discount d=amount->amount*0.05;
        double discamount=double.calcdiscount(grossbill);
        double finalbill=grossbill-discamount;
        System.out.println("Customer: "+name);
        System.out.println("Units: "+units);
        System.out.println("Energy Charge: "+energy);
        System.out.println("Fixed Charge: "+fc);
        System.out.println("Gross Bill: "+grossbill);
        System.out.println("Discount: "+discamount);
        System.out.println("Final Bill: "+finalbill);
    }
}

