    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        String type=sc.next();
        String name=sc.next();
        int att=sc.nextInt();

        GameCharacter a;

        if(type.equals("Warrior")){
            a=new Warrior(name,att);
        }else{
            a=new Mage(name,att,sc.nextInt());
        }

        a.display();
        a.calcpow();
        if(a instanceof Mage m){
            m.spell();
        }
        sc.close();
    }
}

