import java.util.Scanner;
class GameCharacter{
    public String name;
    public int attack;

    GameCharacter(String n,int att){
        name=n;
        attack=att;
    }

    final void display(){
        System.out.println("Character: "+name);
    }

    public void calcpow(){
        System.out.println("Attack Power: "+attack);

    }
}

class Warrior extends GameCharacter{
    Warrior(String n,int att){
        super(n,att);
    }

    @Override
    public void calcpow(){
        System.out.println("Attack Power: "+attack*2);
    }

}

class Mage extends GameCharacter{
    int mana;
    Mage(String n,int att,int m){
        super(n,att);
        mana=m;
    }



    @Override
    public void calcpow(){
        if(mana>=10){
            attack=attack+50;
            System.out.println("Attack Power: "+attack);
        }else{
            System.out.println("Attack Power: "+attack);
        }
    }


    public void spell(){
        if(mana>=10){
            System.out.println("Fireball cast!");
        }else{
            System.out.println("Not enough mana to cast a spell.");
        }
    }
}




public class Main{
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        String type=sc.next();
        String name=sc.next();
        int att=sc.nextInt();

        GameCharacter a;

        if(type.equals("Warrior")){
            a=new Warrior(name,att);
            a.display();
            a.calcpow();
        }
        else if(type.equals("Mage")){
            a=new Mage(name,att,sc.nextInt());
            a.display();
            a.calcpow();
            if(a instanceof Mage){
            ((Mage)a).spell();
        }
        }
        else{
            System.out.println("Invalid Input");
        }


        sc.close();
    }
}

