import java.util.Scanner;

class GameCharacter{
    String name;
    int baseAttack;
    GameCharacter(String name, int baseAttack){
        this.name=name;
        this.baseAttack=baseAttack;
    }
    final void display(){
        System.out.println("Character: "+name);
    }
    int getAttackPower(){
        return baseAttack;
    }
}
class Warrior extends GameCharacter{
    Warrior(String name, int baseAttack){
        super(name, baseAttack);
    }
    int getAttackPower(){
        return baseAttack*2;
    }
}
class Mage extends GameCharacter{
    int mana;
    Mage(String name, int baseAttack){
        super(name, baseAttack);
    }
    int getAttackPower(){
        return baseAttack+50;
