import java.util.Scanner;
class Guest{
    protected String name;
    Guest(String name){
        this.name=name;
    }
    void displayName(){
        System.out.println("Name: "+name);
    }
}
class RegisteredGuest extends Guest{
    protected String type;
    RegisteredGuest(String name, String type){
        super(name);
        this.type=type;
    }
    void displayType(){
        displayName();
        System.out.println("Room Type: "+type);
    }
}
class LoyaltyGuest extends RegisteredGuest{
    private int nights;
    private double discounts;
    LoyaltyGuest(String name, String type, int nights, double discounts){
        super(name, type);
        this.nights=nights;
        this.discounts=discounts;
    }
    double calculateBill(){
        double grossBill;
        double discountAmount;
        double totalBill;
        if (type.equals(Standard)){
            grossBill=1000*nights;
            discountAmount=(grossBill*discounts)/100;
            totalBill=grossBill-discountAmount;
        }
        else if(type.equals(Deluxe)){
            grossBill=2000*nights;
            discountAmount=(grossBill*discounts)/100;
            totalBill=grossBill-discountAmount;
        }
        else{
            grossBill=3500*nights;
            discountAmount=(grossBill*discounts)/100;
            totalBill=grossBill-discountAmount;
        }
        return grossBill,discountAmount,totalBill;
    }
    void displayDetails(){
        displayName();
        displayType();
        System.out.println("Total Bill: "+totalBill);
    }
}

