class LoyaltyGuest extends RegisteredGuide
{
    int num;
    double ldp;
    double gross, dis, tot;
    LoyalGuest(String roomtype, int num, double ldp)
    {
        super(roomtype);
        this.num=num;
        this.ldp=ldp;
    }

    void calculate()
    {
        if(roomtype.equals("Standard"))
            gross = 1000*num;
        else if(roomtype.equals("Deluxe"))
            gross = 2000*num;
        else
            gross = 3500*num;

        dis = gross*ldp/100.0;
        tot = gross - dis;
    }

    void display()
    {
        super.display();
        System.out.println("Total Bill: "+tot);
    }
}

