import java.util.Scanner;
class Guest{
    String name;
    Guest(String name){
        this.name = name;
    }
    void guest(){
        System.out.println("Name: " + name);
    }
}
class RegisteredGuest extends Guest{
    String room;
    RegisteredGuest(String name, String room){
        super(name);
        this.room = room;
    }
    void room_type(){
        System.out.println("Room Type: " + room);
    }
}
class LoyaltyGuest extends RegisteredGuest{
    int nights;
    double loyalty_discount;
    LoyaltyGuest(String name, String room, int nights, double loyalty_discount){
        super(name, room);
        this.nights= nights;
        this.loyalty_discount = loyalty_discount;
    }
    double final_bill(){
        if(room.equals("Standard")){
            return 1000.0*nights*(100.0-loyalty_discount);
        }
        else if(room.equals("Deluxe")){
            return 2000.0*nights*(100.0-loyalty_discount);
        }
        else if(room.equals("Suite")){
            return 3500.0*nights*(100.0-loyalty_discount);
        }
        else{
            return 0.0;
        }
    }
}
public class Main{
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        String name = sc.nextLine();
        String room = sc.nextLine();
        int nights = sc.nextInt();
        double loyalty_discount = sc.nextDouble();
        LoyaltyGuest a = new LoyaltyGuest(name, room, nights,loyalty_discount);
        a.guest();
        a.room_type();
        if(!a.final_bill()){
            System.out.println(a.final_bill());
        }
        else{
            System.out.println("Invalid Input");
        }
        sc.close();
    }
}

