import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int d = sc.nextInt();

        Set<Integer> set = new HashSet<>();

        // Read codes and remove duplicates
        for (int i = 0; i < n; i++) {
            set.add(sc.nextInt());
        }

        // Find the smallest positive free bin code
        int free = 1;

        while (set.contains(free)) {
            free++;
        }

        // Count pairs with difference exactly D
        int pairs = 0;

        if (d != 0) {
            for (int code : set) {
                if (set.contains(code + d)) {
                    pairs++;
                }
            }
        }

        System.out.println("Free: " + free);
        System.out.println("Pairs: " + pairs);
    }
}

