import java.util.Scanner;

public class ProcessSchedulerTemplate {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            // Read all inputs
            int processId = scanner.nextInt();
            int availableMemory = scanner.nextInt();
            int requiredMemory = scanner.nextInt();
            int cpuBurstTime = scanner.nextInt();

            // Validation checks
            if (processId <= 0) {
                throw new IllegalArgumentException("Invalid process ID");
            }
            // More validations...

            // Memory check
            if (requiredMemory > availableMemory) {
                throw new OutOfMemoryError("Insufficient memory");
            }

            // Successful processing
            int remainingMemory = availableMemory - requiredMemory;
            double cpuUtilization = (double) requiredMemory / cpuBurstTime;

            // Output results

        } catch (IllegalArgumentException e) {
            // Handle invalid parameters
        } catch (OutOfMemoryError e) {
            // Handle insufficient memory
        } catch (ArithmeticException | NumberFormatException e) {
            // Handle input errors
        } catch (Exception e) {
            // Handle other errors
        } finally {
            // Always execute cleanup
        }

        scanner.close();
    }
}
```

